"""E-Commerce Order & Inventory Service written with Pydantic v2.

Demonstrates modern Pydantic v2 patterns:
- @field_validator and @model_validator
- model_config = ConfigDict(...)
- Field(..., pattern=...)
- .model_dump() and .model_validate()
"""

import re
from typing import Dict, List, Optional, Self
from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator, model_validator


class Address(BaseModel):
    """Customer shipping address using v2 pattern validation."""

    street: str
    city: str
    state: str
    zip_code: str = Field(..., pattern=r"^\d{5}(-\d{4})?$")

    model_config = ConfigDict(str_strip_whitespace=True)


class User(BaseModel):
    """Customer profile model using v2 field validators and from_attributes."""

    user_id: int
    username: str
    email: str
    is_active: bool = True

    model_config = ConfigDict(from_attributes=True, str_strip_whitespace=True)

    @field_validator("username")
    @classmethod
    def validate_username(cls, v: str) -> str:
        if len(v) < 3:
            raise ValueError("username must be at least 3 characters")
        if not re.match(r"^[a-zA-Z0-9_]+$", v):
            raise ValueError("username can only contain alphanumeric characters and underscores")
        return v.lower()

    @field_validator("email")
    @classmethod
    def validate_email(cls, v: str) -> str:
        if "@" not in v or "." not in v.split("@")[-1]:
            raise ValueError("invalid email format")
        return v.lower()


class OrderItem(BaseModel):
    """Single item in an order."""

    sku: str
    title: str
    quantity: int = Field(..., gt=0)
    unit_price: float = Field(..., gt=0.0)

    @field_validator("sku")
    @classmethod
    def validate_sku(cls, v: str) -> str:
        v = v.upper().strip()
        if not v.startswith("SKU-"):
            raise ValueError("sku must start with SKU-")
        return v


class Order(BaseModel):
    """Customer purchase order with cross-field model validator and assignment validation."""

    order_id: str
    customer: User
    shipping_address: Address
    items: List[OrderItem]
    discount_pct: float = Field(0.0, ge=0.0, le=100.0)
    total_amount: float = 0.0
    internal_notes: Optional[str] = None
    status: str = "pending"

    model_config = ConfigDict(validate_assignment=True)

    @model_validator(mode='after')
    def compute_and_verify_total(self) -> Self:
        items = self.items or []
        subtotal = sum(item.quantity * item.unit_price for item in items)
        discount = self.discount_pct
        object.__setattr__(
            self,
            'total_amount',
            round(subtotal * (1.0 - (discount / 100.0)), 2)
        )
        return self


class OrderService:
    """Business operations for orders."""

    @staticmethod
    def register_customer(payload: dict) -> User:
        """Parse raw dictionary into User model using v2 model_validate."""
        return User.model_validate(payload)

    @staticmethod
    def export_customer_dict(user: User) -> dict:
        """Serialize user to dict using v2 model_dump."""
        return user.model_dump()

    @staticmethod
    def create_order(payload: dict) -> Order:
        """Parse complete order hierarchy using v2 model_validate."""
        return Order.model_validate(payload)

    @staticmethod
    def export_order_summary(order: Order, exclude_internal: bool = True) -> dict:
        """Export order dictionary with excluded internal fields using v2 model_dump."""
        excludes = {"internal_notes"} if exclude_internal else set()
        return order.model_dump(exclude=excludes)

    @staticmethod
    def apply_discount(order: Order, discount: float) -> Order:
        """Update discount; relies on validate_assignment to guard bounds."""
        order.discount_pct = discount
        # Recalculate total using object.__setattr__ to avoid validation recursion
        subtotal = sum(item.quantity * item.unit_price for item in order.items)
        object.__setattr__(
            order,
            'total_amount',
            round(subtotal * (1.0 - (discount / 100.0)), 2)
        )
        return order
